"""Builds AtomForgeIcons.h: the interface icons as a small font compiled into
AtomForge, so every platform shows the same icons without system fonts.

The glyphs are a subset of DejaVu Sans (Bitstream Vera license, see
LICENSE-DejaVu.txt), renamed "AtomForge Icons" as that license asks of
modified fonts. Run with fontTools installed:

    python make_icon_font.py /usr/share/fonts/truetype/dejavu/DejaVuSans.ttf

The code points must match the Icon namespace in src/ui/Fonts.h (Help is a
plain question mark of the text font).
"""
import io
import pathlib
import sys

from fontTools import subset
from fontTools.ttLib import TTFont

CODEPOINTS = [
    0x2750,  # Open      ❐
    0x2B07,  # Save      ⬇
    0x21B6,  # Undo      ↶
    0x21B7,  # Redo      ↷
    0x2302,  # Home      ⌂
    0x27F7,  # Ruler     ⟷
    0x27F3,  # Rotate    ⟳
    0x2139,  # Info      ℹ
    0x26A0,  # Warning   ⚠
    0x2716,  # Error     ✖
    0x2714,  # Check     ✔
    0x271A,  # Add       ✚
    0x2718,  # Delete    ✘
    0x2699,  # Settings  ⚙
    0x270E,  # Build     ✎
    0x2B21,  # Cube      ⬡
    0x25C9,  # Camera    ◉
    0x25A4,  # Folder    ▤
    0x25A1,  # Document  □
    0x25B6,  # Play      ▶
    0x21C9,  # Pipeline  ⇉
    0x26B2,  # Search    ⚲
    0x2016,  # Pause     ‖
    0x21E4,  # Previous  ⇤
    0x21E5,  # Next      ⇥
]


def main(source):
    font = TTFont(source)
    cmap = font.getBestCmap()
    present = [c for c in CODEPOINTS if c in cmap]
    missing = [hex(c) for c in CODEPOINTS if c not in cmap]
    options = subset.Options()
    options.name_IDs = [0, 1, 2, 3, 4, 5, 6]
    options.notdef_outline = True
    options.hinting = False
    subsetter = subset.Subsetter(options)
    subsetter.populate(unicodes=present)
    subsetter.subset(font)
    # A modified font must not carry the Bitstream Vera names.
    for record in font["name"].names:
        if record.nameID in (1, 4, 16):
            record.string = "AtomForge Icons"
        elif record.nameID == 6:
            record.string = "AtomForgeIcons"
    data = io.BytesIO()
    font.save(data)
    blob = data.getvalue()
    here = pathlib.Path(__file__).resolve().parent
    lines = ["// Generated by make_icon_font.py: the interface icons, a subset of DejaVu Sans",
             "// (Bitstream Vera license, LICENSE-DejaVu.txt) renamed \"AtomForge Icons\".",
             "#pragma once", "", "namespace atomforgeIcons", "{",
             f"inline constexpr unsigned int kFontSize = {len(blob)};",
             "alignas(4) inline const unsigned char kFontData[] = {"]
    for start in range(0, len(blob), 20):
        lines.append("    " + ", ".join(f"0x{b:02x}" for b in blob[start:start + 20]) + ",")
    lines += ["};", "}", ""]
    (here / "AtomForgeIcons.h").write_text("\n".join(lines), encoding="ascii")
    print(f"{len(present)} icons, {len(blob)} bytes" + (f"; missing {missing}" if missing else ""))


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf")
